:root {
  --paper: #fff7e8;
  --ink: #26352d;
  --tomato: #d9573e;
}

.soup-card {
  box-sizing: border-box;
  width: 440px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.soup-card header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.soup-card strong {
  font-size: 20px;
  font-weight: 800;
}

.soup-card time {
  font-size: 13px;
  font-weight: 700;
}

.soup-card p {
  line-height: 1.45;
}

.soup-card button {
  padding: 8px 14px;
  color: var(--paper);
  font-weight: 700;
  background: var(--tomato);
  border: 2px solid var(--ink);
  border-radius: 999px;
}
